# Hub de jogos

Plataforma independente que reúne os jogos. A criança escolhe o tema de hiperfoco, escolhe um jogo e o jogo abre sozinho dentro do hub. React 19 + Vite 8 + Phaser 4.2.1 (Node 20.19+ ou 22.12+).

```sh
cd hub
npm install
npm run dev     # http://127.0.0.1:5190
npm test
npm run build
```

## Organização

```
hub/src/
  App.jsx, telas/        o hub: tema -> lista -> aviso -> jogo
  jogos/
    contrato.js          o que o hub espera de um jogo (leia antes de criar um)
    registro.js          catálogo: fonte única dos jogos do hub
    memoria/  sequencia/  chuva-emocoes/  cuidar-amigo/  plataforma-amigo/
  compartilhado/
    temas.js             hiperfocos (trem, aranha, avião, dinossauro)
    arte/                desenhos SVG feitos em código (personagens, rostos, itens)
    kit-phaser/          HUD, efeitos, sons, XP e montarCena() dos jogos do antigo app/
    atividade/           contrato antigo de atividade (usado pela sequência)
```

Regra: **um jogo só importa da própria pasta e de `compartilhado/`**, nunca do hub nem de outro jogo. `tests/hub.test.js` confere isso, e também confere se toda pasta de jogo tem `manifesto.js` e `index.js` e está no registro.

## Como adicionar um jogo

1. Crie `src/jogos/<id>/` (id em minúsculas com hífen).
2. `manifesto.js`: `export default { id, nome, descricao, habilidades, icone }`. Deve ser leve, porque o hub carrega todos para montar a lista.
3. `index.js`: `export function montar(elemento, { tema, nivel, opcoes, aoTerminar, aoSair })`, que desenha o jogo dentro de `elemento` e devolve uma função `desmontar()`. Detalhes em `src/jogos/contrato.js`.
4. Acrescente uma linha em `src/jogos/registro.js`.
5. Para desenvolver sem passar pelo hub: `http://127.0.0.1:5190/jogo.html?id=<id>&tema=trem`. O resultado aparece no console.

O botão **Sair** e a confirmação de saída são do hub, iguais em todos os jogos. O jogo não precisa ter o próprio botão de sair.

## Origem dos jogos

As pastas antigas (`app/`, `memory-game/`, `src/` e `sequencia.html` na raiz) continuam no repositório. Os jogos foram **copiados** para cá. A partir de agora, mudanças nos jogos devem ser feitas aqui.

| Jogo | Veio de |
|---|---|
| memoria | `memory-game/` |
| sequencia | `src/games/sequence/` |
| chuva-emocoes, cuidar-amigo, plataforma-amigo | `app/src/games/` |

## Limitações conhecidas

- A memória tem um único conjunto de figuras (Transportes) para todos os temas. A sequência tem figuras de trem e dinossauro, e os outros temas usam dinossauro.
- O nível é sempre 1 (ainda não há PDI no hub).
- O resultado de cada partida só aparece no console. O ponto para enviar ao servidor é `aoTerminar` em `App.jsx`.
- O XP e a coleção dos jogos do antigo `app/` ficam salvos no navegador (`kit-phaser/progresso.js`).
// Contrato entre o hub e os jogos. O hub só conhece o que está aqui.
//
// Cada jogo fica em jogos/<id>/ com dois arquivos de entrada:
//   manifesto.js  export default { id, nome, descricao, habilidades, icone }
//                 Leve: o hub carrega todos os manifestos para montar a lista.
//   index.js      export function montar(elemento, parametros) → desmontar()
//                 Pesado: o hub só importa quando a criança abre o jogo.
//
// parametros = {
//   tema,        hiperfoco escolhido (compartilhado/temas.js)
//   nivel,       1 a 3, vem do PDI; o hub usa 1 por enquanto
//   opcoes,      { sons, musica, reduzirMovimento }
//   aoTerminar,  (resultado) => void, uma vez por partida
//   aoSair,      () => void, quando o próprio jogo pede para voltar ao hub
// }
// resultado = { status: 'completed' | 'abandoned', attempts, correct, hints },
// o mesmo formato que site/web/src/jogos/integracao.js envia ao servidor.
//
// desmontar() libera tudo (Phaser, eventos, DOM) e, se a partida não terminou,
// chama aoTerminar com status 'abandoned'.
//
// Um jogo só importa da própria pasta e de compartilhado/, nunca do hub nem de
// outro jogo. tests/hub.test.js confere isso.

export const STATUS = ['completed', 'abandoned']

export function validarManifesto(m) {
  if (!m || typeof m.id !== 'string' || !/^[a-z0-9-]+$/.test(m.id)) throw new Error('Manifesto sem id válido.')
  for (const campo of ['nome', 'descricao', 'icone']) {
    if (typeof m[campo] !== 'string' || !m[campo].trim()) throw new Error(`Manifesto "${m.id}" sem ${campo}.`)
  }
  if (!Array.isArray(m.habilidades) || !m.habilidades.length) throw new Error(`Manifesto "${m.id}" sem habilidades.`)
  return m
}

export function criarResultado({ status, attempts = 0, correct = 0, hints = 0 }) {
  if (!STATUS.includes(status)) throw new Error('Estado inválido.')
  if (![attempts, correct, hints].every((n) => Number.isSafeInteger(n) && n >= 0) || correct > attempts) {
    throw new Error('Contadores inválidos.')
  }
  return { status, attempts, correct, hints }
}
// Catálogo do hub: fonte única dos jogos. Para adicionar um jogo, crie jogos/<id>/
// seguindo jogos/contrato.js e acrescente uma linha aqui.
import { validarManifesto } from './contrato.js'
import memoria from './memoria/manifesto.js'
import sequencia from './sequencia/manifesto.js'
import chuvaEmocoes from './chuva-emocoes/manifesto.js'
import cuidarAmigo from './cuidar-amigo/manifesto.js'
import plataformaAmigo from './plataforma-amigo/manifesto.js'

// `carregar` só baixa o código do jogo quando a criança abre ele.
export const JOGOS = [
  { ...memoria, carregar: () => import('./memoria/index.js') },
  { ...sequencia, carregar: () => import('./sequencia/index.js') },
  { ...chuvaEmocoes, carregar: () => import('./chuva-emocoes/index.js') },
  { ...cuidarAmigo, carregar: () => import('./cuidar-amigo/index.js') },
  { ...plataformaAmigo, carregar: () => import('./plataforma-amigo/index.js') },
]

JOGOS.forEach(validarManifesto)

export const jogoPorId = (id) => JOGOS.find((j) => j.id === id) ?? null
{
  "name": "dopamine-hub",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "engines": { "node": "^20.19.0 || >=22.12.0" },
  "scripts": {
    "dev": "vite --host 127.0.0.1 --port 5190 --strictPort",
    "build": "vite build",
    "preview": "vite preview --host 127.0.0.1 --port 4190 --strictPort",
    "test": "node --test \"tests/*.test.js\""
  },
  "dependencies": {
    "@fontsource/fredoka": "^5.3.0",
    "phaser": "4.2.1",
    "react": "^19.3.1",
    "react-dom": "^19.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^6.1.2",
    "vite": "8.3.5"
  }
}
import { resolve } from 'node:path'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  build: {
    // a memória e a sequência só aceitam imagens por URL http(s), não data:
    assetsInlineLimit: 0,
    rolldownOptions: {
      input: {
        hub: resolve(import.meta.dirname, 'index.html'),
        jogo: resolve(import.meta.dirname, 'jogo.html'),
      },
    },
  },
})

