import Phaser from 'phaser';
import { createResult, RESULT_EVENT, validateActivity } from './contracts.js';

export class BaseGameScene extends Phaser.Scene {
  init(activity) {
    this.activity = validateActivity(activity);
    this.metrics = { attempts: 0, correct: 0, hints: 0 };
    this.finished = false;
    this.failedImages = [];
  }
  preload() {
    this.load.on('loaderror', file => this.failedImages.push(file.key));
    for (const image of this.activity.images) this.load.image(image.id, image.url);
  }
  create() {
    if (this.failedImages.length) {
      this.game.events.emit('activity-error', 'Não foi possível carregar as imagens. Volte ao menu e tente novamente.');
      return;
    }
    this.buildBoard();
  }
  buildBoard() {
    this.add.text(480, 90, 'Atividade em preparação', { fontSize: '30px', color: '#183b39' }).setOrigin(0.5);
    this.add.text(480, 145, 'As imagens já estão prontas para o jogo.', { fontSize: '22px', color: '#183b39' }).setOrigin(0.5);
    this.activity.images.forEach((image, i) => this.add.image(480 + (i - (this.activity.images.length - 1) / 2) * 220, 330, image.id).setDisplaySize(180, 180));
  }
  finish(status) {
    if (this.finished) return;
    this.finished = true;
    this.game.events.emit(RESULT_EVENT, createResult(this.activity, { status, ...this.metrics }));
  }
}
export const GAME_IDS = Object.freeze(['memory', 'puzzle', 'sequence']);
export const RESULT_EVENT = 'activity-result';
const requiredImages = { memory: 3, puzzle: 1, sequence: 2 };

export function validateActivity(activity) {
  if (!activity || typeof activity.activityId !== 'string' || !activity.activityId.trim()) throw new Error('Atividade sem identificador.');
  if (!GAME_IDS.includes(activity.gameId)) throw new Error('Jogo desconhecido.');
  if (typeof activity.theme !== 'string' || !activity.theme.trim()) throw new Error('Tema ausente.');
  if (!Array.isArray(activity.images) || activity.images.length !== requiredImages[activity.gameId]) throw new Error('Quantidade de imagens inválida.');
  const ids = new Set();
  for (const image of activity.images) {
    if (!image || typeof image.id !== 'string' || !image.id || typeof image.url !== 'string' || !image.url || typeof image.description !== 'string' || !image.description.trim() || ids.has(image.id)) throw new Error('Imagem inválida ou identificador duplicado.');
    const url = new URL(image.url, 'https://local.invalid');
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('Protocolo de imagem não permitido.');
    ids.add(image.id);
  }
  return activity;
}

// Metrics count user actions: pair comparisons, piece placements, or answer selections.
export function createResult(activity, { status, attempts = 0, correct = 0, hints = 0 }) {
  validateActivity(activity);
  if (!['completed', 'abandoned'].includes(status)) throw new Error('Estado inválido.');
  if (![attempts, correct, hints].every(n => Number.isSafeInteger(n) && n >= 0) || correct > attempts) throw new Error('Contadores inválidos.');
  return { activityId: activity.activityId, gameId: activity.gameId, status, attempts, correct, hints };
}
import dino from './assets/dino.svg';
import ovo from './assets/ovo.svg';
import locomotiva from './assets/locomotiva.svg';
import vagao from './assets/vagao.svg';

// Dados de demonstração próprios: A e B com silhuetas diferentes, sem API.
const THEMES = {
  dinossauros: {
    context: 'Os dinossauros e os ovos fizeram uma fila.',
    images: [
      { id: 'seq-dino', url: dino, description: 'Dinossauro verde', label: 'dino' },
      { id: 'seq-ovo', url: ovo, description: 'Ovo de dinossauro', label: 'ovo' },
    ],
  },
  trem: {
    context: 'O trem está montando os vagões.',
    images: [
      { id: 'seq-locomotiva', url: locomotiva, description: 'Locomotiva verde', label: 'locomotiva' },
      { id: 'seq-vagao', url: vagao, description: 'Vagão-tanque laranja', label: 'vagão' },
    ],
  },
};

export function sequenceDemo({ theme = 'dinossauros', context = true, reducedMotion } = {}) {
  const data = THEMES[theme] ?? THEMES.dinossauros;
  return {
    activityId: crypto.randomUUID(),
    gameId: 'sequence',
    theme: THEMES[theme] ? theme : 'dinossauros',
    ...(context ? { context: data.context } : {}),
    images: data.images.map(image => ({ ...image })),
    settings: { sound: false, reducedMotion: reducedMotion ?? matchMedia('(prefers-reduced-motion: reduce)').matches },
  };
}
import test from 'node:test'
import assert from 'node:assert/strict'
import { readdir, readFile } from 'node:fs/promises'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { criarResultado, validarManifesto } from '../src/jogos/contrato.js'

const JOGOS_DIR = new URL('../src/jogos/', import.meta.url)

async function pastasDeJogos() {
  const itens = await readdir(JOGOS_DIR, { withFileTypes: true })
  return itens.filter((i) => i.isDirectory()).map((i) => i.name)
}

const SRC = fileURLToPath(new URL('../src/', import.meta.url))

// caminhos absolutos dos .js de uma pasta, e o destino de cada import relativo
async function arquivosJs(dir) {
  const itens = await readdir(dir, { withFileTypes: true, recursive: true })
  return itens.filter((i) => i.isFile() && /\.jsx?$/.test(i.name)).map((i) => join(i.parentPath ?? i.path, i.name))
}
async function importsRelativos(arquivo) {
  const codigo = await readFile(arquivo, 'utf8')
  return [...codigo.matchAll(/from\s+'(\.[^']+)'|import\('(\.[^']+)'\)/g)].map((m) => {
    const caminho = m[1] ?? m[2]
    return { caminho, alvo: relative(SRC, resolve(dirname(arquivo), caminho)).split(sep).join('/') }
  })
}

test('cada pasta de jogo tem manifesto.js e index.js, e está no registro', async () => {
  const registro = await readFile(new URL('registro.js', JOGOS_DIR), 'utf8')
  for (const id of await pastasDeJogos()) {
    const arquivos = await readdir(new URL(`${id}/`, JOGOS_DIR))
    assert.ok(arquivos.includes('manifesto.js'), `${id} sem manifesto.js`)
    assert.ok(arquivos.includes('index.js'), `${id} sem index.js`)
    assert.ok(registro.includes(`'./${id}/manifesto.js'`), `${id} fora do registro`)
    assert.ok(registro.includes(`import('./${id}/index.js')`), `${id} sem carregar() no registro`)
    const manifesto = await readFile(new URL(`${id}/manifesto.js`, JOGOS_DIR), 'utf8')
    assert.ok(manifesto.includes(`id: '${id}'`), `${id}: o id do manifesto precisa ser o nome da pasta`)
  }
})

test('um jogo só importa da própria pasta e de compartilhado/', async () => {
  for (const id of await pastasDeJogos()) {
    for (const arquivo of await arquivosJs(join(SRC, 'jogos', id))) {
      for (const { caminho, alvo } of await importsRelativos(arquivo)) {
        const dentro = alvo.startsWith(`jogos/${id}/`) || alvo.startsWith('compartilhado/')
        assert.ok(dentro, `${id}: ${relative(SRC, arquivo)} importa ${caminho}`)
      }
    }
  }
})

test('compartilhado/ não importa nenhum jogo nem o hub', async () => {
  for (const arquivo of await arquivosJs(join(SRC, 'compartilhado'))) {
    for (const { caminho, alvo } of await importsRelativos(arquivo)) {
      assert.ok(alvo.startsWith('compartilhado/'), `${relative(SRC, arquivo)} importa ${caminho}`)
    }
  }
})

test('o manifesto exige id, nome, descrição, ícone e habilidades', () => {
  const ok = { id: 'teste', nome: 'Teste', descricao: 'Um jogo.', icone: '/a.svg', habilidades: ['empatia'] }
  assert.equal(validarManifesto(ok), ok)
  assert.throws(() => validarManifesto({ ...ok, id: 'Com Espaço' }))
  assert.throws(() => validarManifesto({ ...ok, habilidades: [] }))
  assert.throws(() => validarManifesto({ ...ok, icone: '' }))
})

test('o resultado segue o formato que o site envia ao servidor', () => {
  assert.deepEqual(criarResultado({ status: 'completed', attempts: 4, correct: 3 }), { status: 'completed', attempts: 4, correct: 3, hints: 0 })
  assert.throws(() => criarResultado({ status: 'pausado' }))
  assert.throws(() => criarResultado({ status: 'completed', attempts: 1, correct: 2 }))
})
