326	<script>
327	const N = 15, COLS = 5;
328	const DEVICES = {
329	  t8:   { w: 960,  h: 600,  pxcm: 56, desk: false, name: 'Tablet de 8″ na horizontal (≈ 960 × 600 px CSS)' },
330	  t10:  { w: 1024, h: 768,  pxcm: 52, desk: false, name: 'Tablet de 10″ na horizontal (1024 × 768 px CSS)' },
331	  nb:   { w: 1280, h: 650,  pxcm: 38, desk: true,  name: 'Notebook, janela de 1280 × 650 px' },
332	  mon:  { w: 1440, h: 800,  pxcm: 38, desk: true,  name: 'Monitor, janela de 1440 × 800 px' },
333	  port: { w: 768,  h: 1024, pxcm: 52, desk: false, name: 'Tablet de 10″ em retrato (768 × 1024 px CSS)' },
334	};
335	const IMAGES = {
336	  trem:    { ratio: 5 / 3, desc: 'Trem colorido com locomotiva vermelha soltando fumaça, num campo verde com céu azul.' },
337	  baleia:  { ratio: 5 / 3, desc: 'Baleia azul nadando no mar, com um barquinho na superfície e peixes no fundo de areia.' },
338	  foguete: { ratio: 1,     desc: 'Foguete branco e vermelho decolando num céu noturno com estrelas e lua.' },
339	};
340	const icon = {
341	  back: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>',
342	  hint: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9V16h7v-2.1A6 6 0 0 0 12 3z"/></svg>',
343	  soundOff: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M17 9l4 6M21 9l-4 6"/></svg>',
344	  soundOn: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12"/></svg>',
345	  check: '<svg viewBox="0 0 24 24" fill="none" stroke="#2a1f3d" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7"/></svg>',
346	  tablet: '<svg width="200" height="130" viewBox="0 0 200 130" aria-hidden="true"><rect x="14" y="20" width="56" height="90" rx="9" fill="none" stroke="#2a1f3d" stroke-width="4" stroke-dasharray="7 6" opacity=".5"/><rect x="92" y="34" width="96" height="62" rx="9" fill="#fff" stroke="#2a1f3d" stroke-width="4"/><rect x="102" y="44" width="76" height="42" rx="3" fill="#7fc8a9"/><path d="M58 12 Q86 4 104 22" fill="none" stroke="#6a3fc8" stroke-width="5" stroke-linecap="round"/><path d="M92 22 L105 23 L102 10" fill="none" stroke="#6a3fc8" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>',
347	};
348	
349	// ---- Geometria (pixels lógicos 960 x 600) ----
350	const cellXY = c => [362 + (c % COLS) * 96, 94 + Math.floor(c / COLS) * 96];
351	const slotXY = s => {
352	  const row = Math.floor(s / 10), col = s % 10;
353	  const count = row === 0 ? 10 : N - 10;
354	  const rowW = count * 72 + (count - 1) * 12;
355	  return [24 + (912 - rowW) / 2 + col * 84, 418 + row * 84];
356	};
357	const TILTS = [-3, 2, -1.5, 2.5, -2.5, 1, -3, 2, -1, 2.5, -2, 1.5, -3, 2, -1.5];
358	
359	// ---- Estado ----
360	const opts = { img: 'trem', theme: 'trem a vapor no campo', card: '#ffd9a8', guide: false, wrong: 'stay', rm: matchMedia('(prefers-reduced-motion: reduce)').matches, fail: false, sound: false, dev: 't10' };
361	let S, matchNo = 0, timers = [];
362	
363	function shuffled(seed) {
364	  const a = Array.from({ length: N }, (_, i) => i);
365	  let x = seed * 9301 + 49297;
366	  for (let i = N - 1; i > 0; i--) { x = (x * 9301 + 49297) % 233280; const j = Math.floor((x / 233280) * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
367	  return a;
368	}
369	function newMatch() {
370	  matchNo++;
371	  timers.forEach(clearTimeout); timers = [];
372	  const order = shuffled(matchNo + 3);
373	  S = {
374	    phase: 'loading', activityId: `demo-puzzle-${String(matchNo).padStart(3, '0')}`,
375	    slotOf: {}, cellOf: Array(N).fill(null), occ: Array(N).fill(null),
376	    sel: null, hint: null, busy: false, finished: false, confirm: false,
377	    msg: ['Escolha uma peça', ''], metrics: { attempts: 0, correct: 0, hints: 0 },
378	  };
379	  order.forEach((p, s) => { S.slotOf[p] = s; });
380	  buildGame();
381	  render();
382	  later(() => { S.phase = opts.fail ? 'error' : 'start'; render(); }, 700);
383	}
384	const later = (fn, ms) => { const t = setTimeout(fn, ms); timers.push(t); return t; };
385	const isOk = p => S.cellOf[p] === p;
386	const okCount = () => S.cellOf.filter((c, p) => c === p).length;
387	
388	// ---- Som opcional (papel), só depois de um toque e só se ligado ----
389	let actx;
390	function paper() {
391	  if (!opts.sound) return;
392	  try {
393	    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
394	    const len = Math.floor(actx.sampleRate * 0.07), buf = actx.createBuffer(1, len, actx.sampleRate), d = buf.getChannelData(0);
395	    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len) ** 2;
396	    const src = actx.createBufferSource(), f = actx.createBiquadFilter(), g = actx.createGain();
397	    f.type = 'bandpass'; f.frequency.value = 2400; g.gain.value = 0.18;
398	    src.buffer = buf; src.connect(f).connect(g).connect(actx.destination); src.start();
399	  } catch (e) { /* sem som neste navegador */ }
400	}
401	
402	// ---- Montagem do DOM do jogo ----
403	const stage = document.getElementById('stage');
404	const crop = p => `<svg viewBox="${(p % COLS) * 100} ${Math.floor(p / COLS) * 100} 100 100" aria-hidden="true"><use href="#comp" width="500" height="300"/></svg>`;
405	function compose() {
406	  // Monta a imagem no formato 5:3 do tabuleiro: inteira (contain); a sobra recebe a própria imagem ampliada e desfocada.
407	  const id = opts.img, r = IMAGES[id].ratio;
408	  let old = document.getElementById('comp'); if (old) old.remove();
409	  const ns = 'http://www.w3.org/2000/svg', sym = document.createElementNS(ns, 'symbol');
410	  sym.id = 'comp'; sym.setAttribute('viewBox', '0 0 500 300');
411	  if (Math.abs(r - 5 / 3) < 0.01) sym.innerHTML = `<use href="#img-${id}" width="500" height="300"/>`;
412	  else {
413	    const cw = r > 5 / 3 ? 500 : 300 * r, ch = r > 5 / 3 ? 500 / r : 300;
414	    const kw = r > 5 / 3 ? 300 * r : 500, kh = r > 5 / 3 ? 300 : 500 / r;
415	    sym.innerHTML = `<g filter="url(#blur)"><use href="#img-${id}" x="${(500 - kw) / 2}" y="${(300 - kh) / 2}" width="${kw}" height="${kh}"/></g><rect width="500" height="300" fill="#fff" opacity=".22"/><use href="#img-${id}" x="${(500 - cw) / 2}" y="${(300 - ch) / 2}" width="${cw}" height="${ch}"/>`;
416	  }
417	  document.querySelector('svg defs').appendChild(sym);
418	}
419	function buildGame() {
420	  compose();
421	  const cells = Array.from({ length: N }, (_, c) => { const [x, y] = cellXY(c); return `<button type="button" class="cell" data-cell="${c}" style="left:${x}px;top:${y}px" aria-label="Casa linha ${Math.floor(c / COLS) + 1}, coluna ${c % COLS + 1}"></button>`; }).join('');
422	  const slots = Array.from({ length: N }, (_, s) => { const [x, y] = slotXY(s); return `<span class="slot" style="left:${x}px;top:${y}px"></span>`; }).join('');
423	  const pieces = Array.from({ length: N }, (_, p) => `<button type="button" class="pc" data-p="${p}" style="--tilt:${TILTS[S.slotOf[p]]}deg"><span class="in">${crop(p)}</span><span class="badge">${icon.check}</span><span class="tag">Esta peça</span></button>`).join('');
424	  const dots = Array.from({ length: N }, () => '<i></i>').join('');
425	  const desc = IMAGES[opts.img].desc;
426	  stage.innerHTML = `<div class="g" id="g" role="application" aria-label="Quebra-cabeça. ${desc}">
427	    <div class="bar">
428	      <button type="button" class="gbtn" id="b-sair">${icon.back}Sair</button>
429	      <div class="instr" aria-live="polite"><span class="main" id="i-main"></span><span class="sub" id="i-sub"></span></div>
430	      <button type="button" class="gbtn" id="b-ajuda">${icon.hint}Ajuda</button>
431	      <button type="button" class="gbtn" id="b-som" aria-pressed="false"></button>
432	    </div>
433	    <div class="left">
434	      <div class="lbl">Modelo</div>
435	      <div class="pic"><svg viewBox="0 0 500 300" role="img" aria-label="${desc}"><use href="#comp"/></svg></div>
436	      <p class="cap" id="cap"></p>
437	    </div>
438	    <div class="prog"><div class="lbl" id="prog"></div><div class="dots" id="dots">${dots}</div></div>
439	    <div class="boardbg"></div>
440	    <svg class="guide" viewBox="0 0 500 300" aria-hidden="true"><use href="#comp"/></svg>
441	    ${cells}
442	    <div class="traybg"></div>
443	    ${slots}
444	    ${pieces}
445	    <div class="hintbox" id="hintbox"><span>Dica</span></div>
446	    <button type="button" class="back" id="b-back">Devolver aqui</button>
447	    <div class="sticker">Pronto!</div>
448	    <div class="donebox"><div><h2>Você montou a imagem!</h2><p id="done-sub"></p></div><div class="acts"><button type="button" class="gbtn big primary" id="b-again">Montar de novo</button><button type="button" class="gbtn big" id="b-sair2">Sair</button></div></div>
