async (page) => {
  await page.goto('http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&tema=trem');
  const logs = [];
  page.on('console', m => logs.push(m.text()));
  await page.waitForTimeout(1200);
  const z = 1024 / 960, oy = (768 - 600 * z) / 2;
  const tap = async (x, y) => { await page.mouse.click(x * z, y * z + oy); await page.waitForTimeout(260); };
  await tap(480, 464); // Começar
  await page.screenshot({ path: 'qc-jogo.png' });
  // seleciona a primeira peça da bandeja (slot 0) e põe na casa 0
  const slot0 = [24 + (912 - (10 * 72 + 9 * 12)) / 2 + 36, 418 + 36];
  await tap(...slot0);
  await page.screenshot({ path: 'qc-sel.png' });
  await tap(362 + 48, 94 + 48);
  await page.screenshot({ path: 'qc-colocou.png' });
  return { logs, leitor: await page.textContent('.qc-leitor') };
}

