async (page) => {
  const logs = [];
  page.on('console', m => logs.push(m.text()));
  const z = 1024 / 960, oy = (768 - 600 * z) / 2;
  const at = (x, y) => [x * z, y * z + oy];
  const tap = async (x, y, wait = 300) => { await page.mouse.click(...at(x, y)); await page.waitForTimeout(wait); };
  const ajuda = [960 - 24 - 120 - 14 - 68, 36];
  await tap(...ajuda); await tap(...ajuda); // segunda ajuda repetida não conta
  const leitor1 = await page.textContent('.qc-leitor');
  await page.screenshot({ path: 'qc-dica.png' });
  for (let p = 0; p < 15; p++) {
    if (p > 0) await tap(...ajuda);
    const cx = 362 + (p % 5) * 96 + 48, cy = 94 + Math.floor(p / 5) * 96 + 48;
    await page.mouse.click(...at(cx, cy)); await page.mouse.click(...at(cx, cy)); // toque duplo
    await page.waitForTimeout(320);
  }
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'qc-fim.png' });
  return { leitor1, logs };
}

