async (page) => {
  const logs = [];
  page.on('console', m => logs.push(m.text()));
  await page.goto('http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&tema=aranha&rm=1');
  await page.waitForTimeout(2500);
  const z = 1024 / 960, oy = (768 - 600 * z) / 2;
  const at = (x, y) => [x * z, y * z + oy];
  const tap = async (x, y, wait = 700) => { await page.mouse.click(...at(x, y)); await page.waitForTimeout(wait); };
  const ajuda = [960 - 24 - 120 - 14 - 68, 36];
  const cell = p => [362 + (p % 5) * 96 + 48, 94 + Math.floor(p / 5) * 96 + 48];
  await tap(480, 464); // Começar
  await tap(...ajuda); await tap(...ajuda); // repetida não conta
  // erro de propósito: a peça 0 (selecionada pela ajuda) vai para a casa 1
  await tap(...cell(1));
  await page.screenshot({ path: 'qc-rm-erro.png' });
  for (let p = 0; p < 15; p++) {
    await tap(...ajuda);
    await page.mouse.click(...at(...cell(p))); await page.mouse.click(...at(...cell(p)));
    await page.waitForTimeout(700);
  }
  await page.waitForTimeout(1500);
  await page.screenshot({ path: 'qc-rm-fim.png' });
  // sair depois de terminar não envia outro resultado
  await page.evaluate(() => window.__desmontar());
  await page.waitForTimeout(300);
  return logs.filter(l => l.includes('resultado'));
}

