async (page) => {
  const z = 1024 / 960, oy = (768 - 600 * z) / 2;
  await page.goto(`http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&img=foguete&rm=1`);
  await page.waitForTimeout(2500);
  await page.mouse.click(480 * z, 464 * z + oy);
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `qc-foguete2.png` });
  // checa no navegador se algum par de recortes é idêntico (pixel a pixel, em 20x20)
  return page.evaluate(async () => {
    const { composeImage } = await import('/src/jogos/quebra-cabeca/composeImage.js');
    const out = {};
    for (const name of ['trem', 'baleia', 'foguete', 'aranha', 'aviao', 'dinossauro']) {
      const img = new Image(); img.src = `/src/jogos/quebra-cabeca/assets/${name}.svg`; await img.decode();
      const c = composeImage(img), t = document.createElement('canvas'); t.width = 20; t.height = 20;
      const x = t.getContext('2d', { willReadFrequently: true });
      const sig = [];
      for (let p = 0; p < 15; p++) { x.clearRect(0,0,20,20); x.drawImage(c, (p % 5) * 200, Math.floor(p / 5) * 200, 200, 200, 0, 0, 20, 20); sig.push(x.getImageData(0,0,20,20).data); }
      let minDiff = Infinity;
      for (let a = 0; a < 15; a++) for (let b = a + 1; b < 15; b++) { let d = 0; for (let i = 0; i < sig[a].length; i += 4) d += Math.abs(sig[a][i]-sig[b][i]) + Math.abs(sig[a][i+1]-sig[b][i+1]) + Math.abs(sig[a][i+2]-sig[b][i+2]); minDiff = Math.min(minDiff, d / 400); }
      out[name] = Math.round(minDiff * 10) / 10;
    }
    return out; // diferença média mínima por pixel entre dois recortes (0 = iguais)
  });
}

