  const logs = [];
  page.on('console', m => { if (m.text().includes('resultado')) logs.push(m.text()); });
  await page.route('**/assets/trem.svg*', r => r.abort());
  await page.goto('http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&tema=trem');
