  await page.unroute('**/assets/trem.svg*');
  await page.click('[data-acao="retry"]');
  await page.waitForTimeout(3000);
  const depois = { erro: await page.isVisible('.qc-tela[data-estado="error"]'), carregando: await page.isVisible('.qc-tela[data-estado="loading"]') };
  await page.screenshot({ path: 'qc-retry.png' });
  // Sair na tela de erro: rota bloqueada de novo, Sair chama aoSair e o desmontar envia abandoned
  await page.route('**/assets/trem.svg*', r => r.abort());
  await page.goto('http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&tema=trem');
  await page.waitForTimeout(2500);
  await page.click('[data-acao="sair"]');
  await page.waitForTimeout(500);
  const sair = await page.textContent('#raiz');
  await page.unroute('**/assets/trem.svg*');
  return { erroVisivel, depois, sair, logs };
}

