async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 768, height: 1024 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const p = await ctx.newPage();
  await p.goto('http://127.0.0.1:5207/jogo.html?id=quebra-cabeca&tema=dinossauro');
  await p.waitForTimeout(3000);
  const girarRetrato = await p.isVisible('.qc-girar');
  await p.screenshot({ path: 'qc-retrato.png' });
  await p.setViewportSize({ width: 1024, height: 768 });
  await p.waitForTimeout(1500);
  const girarDeitado = await p.isVisible('.qc-girar');
  const z = 1024 / 960, oy = (768 - 600 * z) / 2;
  const tap = async (x, y, w = 1500) => { await p.touchscreen.tap(x * z, y * z + oy); await p.waitForTimeout(w); };
  await tap(480, 464); // Começar
  const slot = s => [24 + (912 - (10 * 72 + 9 * 12)) / 2 + (s % 10) * 84 + 36, 418 + Math.floor(s / 10) * 84 + 36];
  await tap(...slot(3)); // seleciona com toque
  await p.screenshot({ path: 'qc-toque-sel.png' });
  await tap(362 + 48 + 96 * 2, 94 + 48 + 96); // casa 7
  await p.screenshot({ path: 'qc-toque-colocou.png' });
  const leitor = await p.textContent('.qc-leitor');
  const canvas = await p.evaluate(() => { const c = document.querySelector('.qc canvas'); return [c.width, c.height, c.style.width]; });
  await ctx.close();
  return { girarRetrato, girarDeitado, leitor, canvas };
}

