async (page) => {
  const logs = [];
  page.on('console', m => { if (m.text().includes('resultado')) logs.push(m.text()); });
  await page.getByRole('button', { name: 'Começar' }).click();
  await page.waitForTimeout(3500);
  await page.screenshot({ path: 'qc-hub-jogo.png' });
