  const box = await page.locator('.qc canvas').boundingBox();
  const z = Math.min(box.width / 960, box.height / 600), ox = box.x + (box.width - 960 * z) / 2, oy = box.y + (box.height - 600 * z) / 2;
  const tap = async (x, y) => { await page.mouse.click(ox + x * z, oy + y * z); await page.waitForTimeout(1500); };
  await tap(480, 464);
  await tap(24 + (912 - 804) / 2 + 36, 454);
  await tap(362 + 48, 94 + 48);
  await page.screenshot({ path: 'qc-hub-partida.png' });
  await page.getByRole('button', { name: 'Sair' }).click();
  await page.waitForTimeout(400);
  const dialogo = await page.textContent('[role="dialog"]');
  await page.getByRole('dialog').getByRole('button', { name: 'Sair' }).click();
  await page.waitForTimeout(800);
  return { dialogo, logs, canvasRestante: await page.locator('.qc').count() };
}

